{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Vismodegib, a heteroaromatic amide with a chlorophenyl and pyridine, has an absolute oral bioavailability of 31.8% in humans after a 150 mg dose, directly supporting F >= 20% for the query's similar amide/heteroaromatic framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Sorafenib, an N-methyl heteroaromatic carboxamide with aryl ether/heteroaromatic features, has an oral bioavailability of 38-49% in patients, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Belumosudil, which contains an amide, heteroaromatic rings, and an indazole-like motif, has an absolute oral bioavailability of 64% after a 200 mg oral dose, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tenoxicam, a heteroaromatic amide with a sulfone-related structure, is essentially 100% orally bioavailable in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "CJ-13,610, a thioether-containing heteroaromatic drug, has a reported oral bioavailability of 47% in humans, supporting high bioavailability for the query's thioether-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Glafenine, an aromatic amide/ester with a chloro-quinoline system, has an absolute oral bioavailability of approximately 33% in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "One sorafenib estimate reports approximately 8.5% oral bioavailability, but this is an outlier contradicted by multiple other human estimates of 38-49% and is less transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most structurally related heteroaromatic amides and thioether-containing drugs have human absolute oral bioavailability values of 30-100%, strongly supporting F >= 20% for the query. The single low sorafenib estimate is outweighed by multiple higher direct measurements and by the overall consistent high-bioavailability pattern.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule.",
    "Morgan similarities to the evidence molecules are modest (roughly 0.19-0.26), limiting direct transferability.",
    "Sorafenib bioavailability varies by formulation, dose, and study, introducing some uncertainty.",
    "Some evidence comes from animal or model-based reports rather than human absolute bioavailability studies."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

